WITH unpacked AS (SELECT id, latency_ms, payload_json, context, context['region'] AS region, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, context['version'] AS version, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs) SELECT tier, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN tier = 'pro' THEN 1 END), 0), 2) AS latency_ms_per_pro, COUNT(*) AS cnt, MIN(latency_ms) AS min_latency_ms, COUNT(*) FILTER (WHERE tier = 'gold') AS gold_rows, SIZE(COLLECT_SET(tier)) AS num_tiers, SUM(CASE WHEN tier = 'free' THEN latency_ms ELSE 0 END) AS free_latency_ms FROM unpacked GROUP BY CUBE (tier)
